import { motion } from "framer-motion";
import { cn } from "../lib/utils";
import moneyWoman from "../money-woman.png";

function ElegantShape({
    className,
    delay = 0,
    width = 400,
    height = 100,
    rotate = 0,
    gradient = "from-white/[0.08]",
}) {
    return (
        <motion.div
            initial={{
                opacity: 0,
                y: -150,
                rotate: rotate - 15,
            }}
            animate={{
                opacity: 1,
                y: 0,
                rotate: rotate,
            }}
            transition={{
                duration: 2.4,
                delay,
                ease: [0.23, 0.86, 0.39, 0.96],
                opacity: { duration: 1.2 },
            }}
            className={cn("absolute", className)}
        >
            <motion.div
                animate={{
                    y: [0, 15, 0],
                }}
                transition={{
                    duration: 12,
                    repeat: Number.POSITIVE_INFINITY,
                    ease: "easeInOut",
                }}
                style={{
                    width,
                    height,
                }}
                className="relative"
            >
                <div
                    className={cn(
                        "absolute inset-0 rounded-full",
                        "bg-gradient-to-r to-transparent",
                        gradient,
                        "backdrop-blur-[2px] border-2 border-white/[0.15]",
                        "shadow-[0_8px_32px_0_rgba(255,255,255,0.1)]",
                        "after:absolute after:inset-0 after:rounded-full",
                        "after:bg-[radial-gradient(circle_at_50%_50%,rgba(255,255,255,0.2),transparent_70%)]"
                    )}
                />
            </motion.div>
        </motion.div>
    );
}

export function AnimatedBackground() {
    return (
        <div className="absolute inset-0 overflow-hidden">
            {/* Base gradient background */}
            <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/[0.05] via-transparent to-rose-500/[0.05] blur-3xl" />
            
            {/* Money Woman Image - Beautifully integrated */}
            <motion.div
                initial={{ opacity: 0, scale: 0.8, x: 100 }}
                animate={{ opacity: 1, scale: 1, x: 0 }}
                transition={{ duration: 2, delay: 0.8, ease: [0.23, 0.86, 0.39, 0.96] }}
                className="absolute right-0 top-1/2 transform -translate-y-1/2 pointer-events-none"
            >
                <motion.div
                    animate={{ 
                        y: [0, -20, 0],
                        rotate: [0, 2, 0]
                    }}
                    transition={{
                        duration: 8,
                        repeat: Number.POSITIVE_INFINITY,
                        ease: "easeInOut",
                    }}
                    className="relative"
                >
                    <img
                        src={moneyWoman}
                        alt="Money Woman"
                        className="w-80 h-auto object-contain opacity-20 mix-blend-overlay"
                        style={{
                            filter: 'drop-shadow(0 20px 40px rgba(147, 51, 234, 0.3))',
                        }}
                    />
                    
                    {/* Glowing effect around the image */}
                    <div className="absolute inset-0 bg-gradient-to-r from-purple-500/10 via-pink-500/10 to-purple-500/10 blur-2xl rounded-full" />
                    
                    {/* Animated sparkles around the money woman */}
                    <motion.div
                        animate={{
                            scale: [1, 1.2, 1],
                            opacity: [0.3, 0.7, 0.3],
                        }}
                        transition={{
                            duration: 3,
                            repeat: Number.POSITIVE_INFINITY,
                            ease: "easeInOut",
                        }}
                        className="absolute -top-10 -right-10 w-4 h-4 bg-gradient-to-r from-yellow-400 to-orange-400 rounded-full blur-sm"
                    />
                    
                    <motion.div
                        animate={{
                            scale: [1, 1.3, 1],
                            opacity: [0.2, 0.8, 0.2],
                        }}
                        transition={{
                            duration: 4,
                            repeat: Number.POSITIVE_INFINITY,
                            ease: "easeInOut",
                            delay: 1,
                        }}
                        className="absolute -bottom-8 -left-8 w-3 h-3 bg-gradient-to-r from-green-400 to-emerald-400 rounded-full blur-sm"
                    />
                    
                    <motion.div
                        animate={{
                            scale: [1, 1.1, 1],
                            opacity: [0.4, 0.6, 0.4],
                        }}
                        transition={{
                            duration: 5,
                            repeat: Number.POSITIVE_INFINITY,
                            ease: "easeInOut",
                            delay: 2,
                        }}
                        className="absolute top-1/4 -left-12 w-2 h-2 bg-gradient-to-r from-blue-400 to-cyan-400 rounded-full blur-sm"
                    />
                </motion.div>
            </motion.div>
            
            {/* Floating geometric shapes */}
            <ElegantShape
                delay={0.3}
                width={600}
                height={140}
                rotate={12}
                gradient="from-indigo-500/[0.15]"
                className="left-[-10%] md:left-[-5%] top-[15%] md:top-[20%]"
            />

            <ElegantShape
                delay={0.5}
                width={500}
                height={120}
                rotate={-15}
                gradient="from-rose-500/[0.15]"
                className="right-[-5%] md:right-[0%] top-[70%] md:top-[75%]"
            />

            <ElegantShape
                delay={0.4}
                width={300}
                height={80}
                rotate={-8}
                gradient="from-violet-500/[0.15]"
                className="left-[5%] md:left-[10%] bottom-[5%] md:bottom-[10%]"
            />

            <ElegantShape
                delay={0.6}
                width={200}
                height={60}
                rotate={20}
                gradient="from-amber-500/[0.15]"
                className="right-[15%] md:right-[20%] top-[10%] md:top-[15%]"
            />

            <ElegantShape
                delay={0.7}
                width={150}
                height={40}
                rotate={-25}
                gradient="from-cyan-500/[0.15]"
                className="left-[20%] md:left-[25%] top-[5%] md:top-[10%]"
            />

            {/* Additional overlay for better text readability */}
            <div className="absolute inset-0 bg-gradient-to-t from-slate-900/20 via-transparent to-slate-900/20 pointer-events-none" />
        </div>
    );
}
